/**
 * Context & Proxy factory — builds the typed `ctx` object passed to each
 * fluent action method.
 *
 * At the TypeScript level, ctx.trigger.vendorName is Ref<string>.
 * At runtime, a Proxy intercepts the property access and returns a Ref
 * with the correct RefData ({ kind: "trigger", name: "vendorName" }).
 *
 * This bridges compile-time type safety with runtime reference building.
 */
import { createRef } from "./ref.js";
// ---------------------------------------------------------------------------
// Proxy factories
// ---------------------------------------------------------------------------
/**
 * Ref to a trigger output path; further property access extends `name`
 * with dot segments, mirroring action output refs.
 * ctx.trigger.record.summary → { kind: "trigger", name: "record.summary" }
 */
function createTriggerFieldRef(path) {
    const base = createRef({ kind: "trigger", name: path });
    return new Proxy(base, {
        get(target, prop, receiver) {
            if (typeof prop === "symbol" || prop === "__data" || prop === "__type" || prop === "__calculationType") {
                return Reflect.get(target, prop, receiver);
            }
            return createTriggerFieldRef(`${path}.${String(prop)}`);
        },
    });
}
/**
 * Creates a proxy that intercepts property access and returns trigger Refs.
 * Top-level access returns a deep ref so nested field drilling works:
 *   ctx.trigger.vendorName  → Ref { kind: "trigger", name: "vendorName" }
 *   ctx.trigger.record.id   → Ref { kind: "trigger", name: "record.id" }
 */
export function createTriggerProxy() {
    return new Proxy({}, {
        get(_target, prop) {
            if (typeof prop === "symbol")
                return undefined;
            return createTriggerFieldRef(prop);
        },
    });
}
/**
 * Ref to an action output path; further property access extends `name` with dot
 * segments (`record.id` → `{ kind: "task", actionRefKey, name: "record.id" }`).
 */
function createActionOutputFieldRef(actionRefKey, outputPath) {
    const base = createRef({ kind: "task", actionRefKey, name: outputPath });
    return new Proxy(base, {
        get(target, prop, receiver) {
            if (typeof prop === "symbol" || prop === "__data" || prop === "__type" || prop === "__calculationType") {
                return Reflect.get(target, prop, receiver);
            }
            return createActionOutputFieldRef(actionRefKey, `${outputPath}.${String(prop)}`);
        },
    });
}
/**
 * Creates a proxy for a single action's outputs.
 * ctx.actions.findVendor.records → Ref with
 * { kind: "task", actionRefKey: "findVendor", name: "records" }
 */
export function createActionOutputProxy(actionRefKey) {
    return new Proxy({}, {
        get(_target, prop) {
            if (typeof prop === "symbol")
                return undefined;
            return createActionOutputFieldRef(actionRefKey, String(prop));
        },
    });
}
/**
 * Creates a proxy for the actions namespace.
 * ctx.actions → Proxy where each property access returns an action output proxy.
 */
export function createActionsProxy(actionNames) {
    const cache = new Map();
    return new Proxy({}, {
        get(_target, prop) {
            if (typeof prop === "symbol")
                return undefined;
            if (!cache.has(prop)) {
                cache.set(prop, createActionOutputProxy(prop));
            }
            return cache.get(prop);
        },
        ownKeys() {
            return actionNames;
        },
        getOwnPropertyDescriptor(_target, prop) {
            if (typeof prop === "symbol")
                return undefined;
            if (actionNames.includes(prop)) {
                return { configurable: true, enumerable: true, writable: false };
            }
            return undefined;
        },
    });
}
/**
 * Creates a forEach item proxy.
 * item.fieldName → Ref with { kind: "forEach", forEachActionName, name: "fieldName" }
 * Accessing the item directly (without a property) returns a Ref to the whole item.
 */
export function createForEachItemProxy(forEachActionName) {
    const baseRef = createRef({ kind: "forEach", forEachActionName, name: "item" });
    return new Proxy(baseRef, {
        get(target, prop) {
            if (typeof prop === "symbol" || prop === "__data" || prop === "__type" || prop === "__calculationType") {
                return target[prop];
            }
            return createRef({ kind: "forEach", forEachActionName, name: prop });
        },
    });
}
/**
 * Variables proxy. The first-level access is a HYBRID (same pattern as
 * {@link createForEachItemProxy}): it is itself a Ref to the variable named
 * after the action — the fluent form, `ctx.variables.greeting` — AND a proxy
 * whose further property access yields per-variable refs — the generic form,
 * `ctx.variables.actionName.varName`, for variable actions creating several
 * variables. Both produce { kind: "variableParam", variableActionRefKey, name }.
 */
function createVariablesProxy() {
    return new Proxy({}, {
        get(_target, actionName) {
            if (typeof actionName === "symbol")
                return undefined;
            const action = String(actionName);
            const base = createRef({ kind: "variableParam", variableActionRefKey: action, name: action });
            return new Proxy(base, {
                get(target, varName, receiver) {
                    if (typeof varName === "symbol" || varName === "__data" || varName === "__type" || varName === "__calculationType") {
                        return Reflect.get(target, varName, receiver);
                    }
                    return createRef({ kind: "variableParam", variableActionRefKey: action, name: String(varName) });
                },
            });
        },
    });
}
/**
 * Build a complete Context object for a given point in the chain.
 *
 * `TVariables` is a phantom — it only affects the compile-time shape of
 * `ctx.variables`. The runtime proxy is still an open-ended lookup.
 */
export function buildContext(actionNames) {
    return {
        trigger: createTriggerProxy(),
        actions: createActionsProxy(actionNames),
        variables: createVariablesProxy(),
    };
}
